def normalize_isbn(value):
    if value is None:
        return "INVALID: missing ISBN"
    s = str(value).strip()
    if not s:
        return "INVALID: empty ISBN"
    low = s.lower()
    for lab in ("isbn-13:", "isbn-10:", "isbn13:", "isbn10:", "isbn:", "isbn-13", "isbn-10", "isbn13", "isbn10", "isbn"):
        if low.startswith(lab):
            s = s[len(lab):].strip()
            break
    if s.lower().startswith("urn:isbn:"):
        s = s[9:].strip()
    s = s.replace("-", "").replace(" ", "").replace("\u2013", "").replace("\u2014", "")
    if not s:
        return "INVALID: empty ISBN"
    if len(s) == 10:
        body = s[:9]
        if not body.isdigit():
            return "INVALID: ISBN-10 must have 9 leading digits"
        last = s[9].upper()
        if not (last.isdigit() or last == "X"):
            return "INVALID: ISBN-10 check character must be digit or X"
        total = sum((10 - i) * int(body[i]) for i in range(9))
        total += 10 if last == "X" else int(last)
        if total % 11 != 0:
            return "INVALID: ISBN-10 check digit failed"
        core = "978" + body
        chk = (10 - sum((1 if i % 2 == 0 else 3) * int(core[i]) for i in range(12)) % 10) % 10
        return core + str(chk)
    if len(s) == 13:
        if not s.isdigit():
            return "INVALID: ISBN-13 must be all digits"
        total = sum((1 if i % 2 == 0 else 3) * int(s[i]) for i in range(12))
        if (10 - total % 10) % 10 != int(s[12]):
            return "INVALID: ISBN-13 check digit failed"
        return s
    return "INVALID: not a 10- or 13-digit ISBN"
